#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NumpyDType {
    UInt8,
    Int8,
    UInt16,
    Int16,
    Float16,
    UInt32,
    Int32,
    Float32,
    UInt64,
    Int64,
    Float64,
    Complex64,
    Complex128,
}

impl NumpyDType {
    fn dtype_size(&self) -> u8 {
        match self {
            NumpyDType::UInt8 | NumpyDType::Int8 => 8,
            NumpyDType::UInt16 | NumpyDType::Int16 | NumpyDType::Float16 => 16,
            NumpyDType::UInt32 | NumpyDType::Int32 | NumpyDType::Float32 => 32,
            NumpyDType::UInt64 | NumpyDType::Int64 | NumpyDType::Float64 | NumpyDType::Complex64 => 64,
            NumpyDType::Complex128 => 128,
        }
    }

    fn dtype_kind_order(&self) -> u8 {
        match self {
            NumpyDType::UInt8 | NumpyDType::UInt16 | NumpyDType::UInt32 | NumpyDType::UInt64 => 0,
            NumpyDType::Int8 | NumpyDType::Int16 | NumpyDType::Int32 | NumpyDType::Int64 => 1,
            NumpyDType::Float16 | NumpyDType::Float32 | NumpyDType::Float64 => 2,
            NumpyDType::Complex64 | NumpyDType::Complex128 => 3,
        }
    }

    fn can_represent_value(&self, v: i8) -> bool {
        match self {
            // Unsigned ints: only non-negative values within range
            NumpyDType::UInt8 => v >= 0,
            NumpyDType::UInt16 => v >= 0,
            NumpyDType::UInt32 => v >= 0,
            NumpyDType::UInt64 => v >= 0,

            // Signed ints: always true because v is i8 and underlying type >= 8bits
            NumpyDType::Int8 => true,
            NumpyDType::Int16 => true,
            NumpyDType::Int32 => true,
            NumpyDType::Int64 => true,

            // Floats and Complex: can represent any i8 integer per problem statement
            NumpyDType::Float16 => true,
            NumpyDType::Float32 => true,
            NumpyDType::Float64 => true,
            NumpyDType::Complex64 => true,
            NumpyDType::Complex128 => true,
        }
    }
}

pub fn min_scalar_type(value: i8) -> NumpyDType {
    let candidates = [
        NumpyDType::UInt8,
        NumpyDType::Int8,
        NumpyDType::UInt16,
        NumpyDType::Int16,
        NumpyDType::Float16,
        NumpyDType::UInt32,
        NumpyDType::Int32,
        NumpyDType::Float32,
        NumpyDType::UInt64,
        NumpyDType::Int64,
        NumpyDType::Float64,
        NumpyDType::Complex64,
        NumpyDType::Complex128,
    ];

    // Filter to types that can represent value
    let mut suitable: Vec<NumpyDType> = candidates
        .iter()
        .copied()
        .filter(|dt| dt.can_represent_value(value))
        .collect();

    // Find minimal bit size
    if suitable.is_empty() {
        // Just return Complex128 as a fallback (should never happen for i8 input)
        return NumpyDType::Complex128;
    }
    suitable.sort_unstable_by_key(|dt| dt.dtype_size());
    let min_size = suitable[0].dtype_size();

    // Keep only those with minimal size
    suitable.retain(|dt| dt.dtype_size() == min_size);

    // Among them, choose the one with minimal kind order
    suitable.sort_unstable_by_key(|dt| dt.dtype_kind_order());

    suitable[0]
}